// Shared checks every Evergreen agent passes. Generated by scripts/new-agent.mjs.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtempSync, existsSync, readFileSync, cpSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { runEvalFile, undocumentedArgs, ONE_CLICK_CATEGORIES, AgentRuntime } from 'evergreen-core';
import { manifest } from '../src/index.js';

const bin = fileURLToPath(new URL('../bin/cedar-of-payer-source.js', import.meta.url));
const fixtures = fileURLToPath(new URL('../fixtures', import.meta.url));

test('every tool argument is described and every enum has a type', () => {
  assert.deepEqual(undocumentedArgs(manifest), []);
  const walk = (s, path) => { if (!s || typeof s !== 'object') return; if (s.enum) assert.ok(s.type, `${path} enum has no type`); for (const [k, v] of Object.entries(s.properties || {})) walk(v, `${path}.${k}`); if (s.items) walk(s.items, `${path}[]`); };
  for (const t of manifest.tools) walk(t.inputSchema, t.name);
});

test('one-click categories are never allow, and the default is block', () => {
  for (const t of manifest.tools) if (ONE_CLICK_CATEGORIES.includes(t.category)) { const r = manifest.policy.rules.find((x) => x.tool === t.name); assert.ok(r && r.decision !== 'allow', t.name); }
  assert.deepEqual(manifest.policy.rules.at(-1), { ...manifest.policy.rules.at(-1), tool: '*', decision: 'block' });
});

test('private evals all pass, at least ten of them', async () => {
  const r = await runEvalFile(manifest, fileURLToPath(new URL('../evals/cases.json', import.meta.url)));
  for (const c of r.results) assert.ok(c.pass, `${c.id}: ${c.fails.join('; ')}`);
  assert.ok(r.total >= 10, 'at least ten eval cases');
});

test('no resident identifier from the fixtures reaches a result (masking on), in any eval case', async () => {
  const canaries = JSON.parse(readFileSync(new URL('../fixtures/phi-canaries.json', import.meta.url), 'utf8')).values.map((v) => v.toLowerCase());
  assert.ok(canaries.length >= 3, 'list the fictional resident identifiers used in the fixtures');
  const data = JSON.parse(readFileSync(new URL('../evals/cases.json', import.meta.url), 'utf8'));
  const root = fileURLToPath(new URL('../evals/' + (data.root || '.') + '/', import.meta.url));
  for (const c of data.cases) {
    const rt = new AgentRuntime(manifest, { root, stateDir: null, audit: false, mode: c.mode || 'assist', autoActions: c.auto_actions || [] });
    if (c.approve) { const pre = await rt.call(c.tool, c.args || {}); if (pre.approval_id) rt.approvals.approve(pre.approval_id, String(c.approve)); }
    const out = JSON.stringify(await rt.call(c.tool, c.args || {})).toLowerCase();
    for (const v of canaries) assert.ok(!out.includes(v), `${c.id} returns "${v}" to the model`);
  }
});

test('the report keeps real names in the files for staff, while the result to the model stays masked', async () => {
  const data = JSON.parse(readFileSync(new URL('../evals/cases.json', import.meta.url), 'utf8'));
  const c = data.cases.find((x) => /_write_report$/.test(x.tool) && (!x.expect || x.expect.status !== 'error'));
  assert.ok(c, 'an eval case runs the report tool');
  const canaries = JSON.parse(readFileSync(new URL('../fixtures/phi-canaries.json', import.meta.url), 'utf8')).values;
  const src = fileURLToPath(new URL('../evals/' + (data.root || '.') + '/', import.meta.url));
  const root = mkdtempSync(join(tmpdir(), 'cedar-of-payer-source-report-'));
  cpSync(src, root, { recursive: true, filter: (p) => !/[\\/](node_modules|evergreen-out|remedy-out|\.remedy)([\\/]|$)/.test(p) });
  const rt = new AgentRuntime(manifest, { root, stateDir: null, audit: false });
  const r = await rt.call(c.tool, { ...c.args, out_dir: 'evergreen-out/report-test' });
  assert.equal(r.status, 'executed', r.reason);
  const files = r.result.files.map((f) => join(root, f));
  for (const f of files) assert.ok(existsSync(f), f);
  const csv = readFileSync(files.find((f) => f.endsWith('.csv')), 'utf8');
  assert.match(csv.split('\n')[0], /owner,decision/);
  const out = JSON.stringify(r).toLowerCase();
  for (const v of canaries) assert.ok(!out.includes(v.toLowerCase()), `report result returns "${v}"`);
  if (!data.no_names_in_report) assert.ok(canaries.some((v) => csv.includes(v)), 'the CSV for staff keeps at least one real value');
});

test('stdio MCP: initialize, list, refuse an unknown tool, write the audit log', async () => {
  const state = mkdtempSync(join(tmpdir(), 'cedar-of-payer-source-mcp-'));
  const child = spawn(process.execPath, [bin, 'mcp', '--root', fixtures, '--state-dir', state], { stdio: ['pipe', 'pipe', 'pipe'] });
  let buf = ''; const waiting = new Map(); let id = 0;
  child.stdout.on('data', (d) => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue; const m = JSON.parse(line); const w = waiting.get(m.id); if (w) { waiting.delete(m.id); w(m); } } });
  const request = (method, params) => new Promise((resolve, reject) => { const my = ++id; const t = setTimeout(() => reject(new Error('timeout ' + method)), 10000); waiting.set(my, (m) => { clearTimeout(t); resolve(m); }); child.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: my, method, params }) + '\n'); });
  try {
    const init = await request('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'smoke', version: '0' } });
    assert.equal(init.result.serverInfo.name, 'cedar-of-payer-source');
    child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
    const list = await request('tools/list', {});
    const names = list.result.tools.map((t) => t.name);
    for (const t of manifest.tools) assert.ok(names.includes(t.name), t.name);
    const blocked = await request('tools/call', { name: 'shell_exec', arguments: { cmd: 'whoami' } });
    assert.equal(blocked.result.isError, true);
    assert.ok(existsSync(join(state, 'audit.jsonl')));
  } finally { child.kill(); }
});
